import Foundation
import Observation

/// How RPCS3's desktop settings dialog presents the settings: tabs, groups, labels and
/// descriptions (settings_layout.json, generated by scripts/gen-settings-layout.py).
struct SettingsLayout: Decodable {
    struct Item: Decodable, Hashable {
        let path: [String]
        let label: String
        let description: String
    }

    struct Group: Decodable, Hashable {
        let title: String
        let items: [Item]
    }

    struct Tab: Decodable, Hashable {
        let title: String
        let groups: [Group]
    }

    let tabs: [Tab]

    static let shared: SettingsLayout = {
        guard let url = Bundle.main.url(forResource: "settings_layout", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let layout = try? JSONDecoder().decode(SettingsLayout.self, from: data) else {
            return SettingsLayout(tabs: [])
        }
        return layout
    }()

}

/// One setting as the core describes it (rpcs3_ios_settings in core/rpcs3_ios.h).
struct Setting: Decodable, Identifiable, Hashable {
    enum Kind: String, Decodable {
        case bool, `enum`, int, uint, float, string
    }

    let path: [String]
    let type: Kind
    let value: String
    /// What resetting gives: the default, or for a game the global value.
    let reset: String
    /// Takes effect while a game runs; otherwise from the next boot.
    let dynamic: Bool
    let options: [String]?
    let min: String?
    let max: String?
    /// For a game: whether it sets this itself instead of following the global settings.
    let overridden: Bool?

    var id: [String] { path }
    var isChanged: Bool { overridden ?? (value != reset) }
}

/// The global settings, or one game's own settings over them.
@Observable
@MainActor
final class SettingsStore {
    /// nil: the global settings.
    let gameID: String?
    let gameTitle: String?

    private(set) var settings: [[String]: Setting] = [:]
    private(set) var isGameRunning = false
    var lastError: String?

    init(gameID: String? = nil, gameTitle: String? = nil) {
        self.gameID = gameID
        self.gameTitle = gameTitle
        reload()
    }

    func setting(_ path: [String]) -> Setting? { settings[path] }

    /// Settings no tab shows, by their place in the configuration.
    var otherSettings: [Setting] {
        let shown = Set(SettingsLayout.shared.tabs.flatMap { $0.groups.flatMap { $0.items.map(\.path) } })
            .union(SettingsPolicy.placed.keys)
        return settings.values
            .filter { !shown.contains($0.path) && !SettingsPolicy.isHidden($0.path) }
            .sorted { $0.path.lexicographicallyPrecedes($1.path) }
    }

    func reload() {
        guard let pointer = gameID.withCString({ core_settings($0) }) else { return }
        defer { core_free(pointer) }

        struct Reply: Decodable {
            let running: Bool
            let settings: [Setting]
        }

        do {
            let reply = try JSONDecoder().decode(Reply.self, from: Data(String(cString: pointer).utf8))
            isGameRunning = reply.running
            settings = Dictionary(reply.settings.map { ($0.path, $0) }, uniquingKeysWith: { first, _ in first })
        } catch {
            lastError = "The settings could not be read: \(error.localizedDescription)"
        }
    }

    func set(_ setting: Setting, to value: String) {
        guard value != setting.value else { return }
        var error = [CChar](repeating: 0, count: 512)
        let result = gameID.withCString { game in
            core_setting_set(game, setting.path.joined(separator: "\n"), value, &error, error.count)
        }
        if result != 0 { lastError = String(cString: error) }
        reload()
    }

    func reset(_ setting: Setting) {
        var error = [CChar](repeating: 0, count: 512)
        let result = gameID.withCString { game in
            core_setting_reset(game, setting.path.joined(separator: "\n"), &error, error.count)
        }
        if result != 0 { lastError = String(cString: error) }
        reload()
    }
}

private extension Optional where Wrapped == String {
    /// Calls body with the C string, or NULL for nil (the global settings).
    func withCString<Result>(_ body: (UnsafePointer<CChar>?) -> Result) -> Result {
        switch self {
        case .some(let text): text.withCString { body($0) }
        case .none: body(nil)
        }
    }
}
